-- «مرکز درخواست‌ها» + «یادآوری مهلت» (owner request, 2026-10-20; docs/decisions.md «یادآوری مهلت و مرکز درخواست‌ها»,
-- docs/db.md workspace.request_sla). Additive only: one new tenant table, nothing existing is changed, no backfill (a
-- request sent before this migration has no clock — docs/decisions.md). The table is generated by drizzle-kit below
-- (src/db/schema/workspace.ts `requestSla`); it holds no text (ids, kind, school, times), so it has tenant RLS only —
-- the system actor of the jobs (no person) must read it, and the manager list narrows it by school in the service.
-- This file adds, after it:
-- 1) defense in depth for "never DELETE": a RESTRICTIVE DELETE policy for app_rw whose USING is false (as 0027 did —
--    a policy, not a REVOKE in app.apply_grants(), so this migration does not redefine that function). Seeds and the
--    pilot reset run as app_owner, pg_dump as app_backup — the policy is TO app_rw only; apply_rls() never drops it.
-- 2) the three apply_* calls (grants, tenant RLS ENABLE + FORCE, the updated_at trigger) for the new table.
-- The new notification types (work_item.overdue, work_item.response_due, work_item.escalated) are catalog rows
-- (scripts/catalog.ts), written by the deploy's `seed` step.
CREATE TABLE "workspace"."request_sla" (
	"id" uuid PRIMARY KEY NOT NULL,
	"organization_id" uuid NOT NULL,
	"school_id" uuid NOT NULL,
	"kind" text NOT NULL,
	"work_item_id" uuid,
	"opened_at" timestamp with time zone DEFAULT now() NOT NULL,
	"period_started_at" timestamp with time zone NOT NULL,
	"due_at" timestamp with time zone NOT NULL,
	"warned_at" timestamp with time zone,
	"escalation_level" smallint DEFAULT 0 NOT NULL,
	"escalated_at" timestamp with time zone,
	"closed_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "request_sla_org_id_uq" UNIQUE("organization_id","id"),
	CONSTRAINT "request_sla_kind_chk" CHECK ("workspace"."request_sla"."kind" IN ('admin_request', 'parent_message', 'leave_request')),
	CONSTRAINT "request_sla_work_item_chk" CHECK ("workspace"."request_sla"."kind" = 'leave_request' OR "workspace"."request_sla"."work_item_id" IS NOT NULL),
	CONSTRAINT "request_sla_period_chk" CHECK ("workspace"."request_sla"."due_at" > "workspace"."request_sla"."period_started_at" AND "workspace"."request_sla"."period_started_at" >= "workspace"."request_sla"."opened_at"),
	CONSTRAINT "request_sla_escalation_chk" CHECK ("workspace"."request_sla"."escalation_level" BETWEEN 0 AND 10 AND ("workspace"."request_sla"."escalation_level" = 0) = ("workspace"."request_sla"."escalated_at" IS NULL))
);
